import{_ as t,o as r,c as o,j as e,a as s}from"./chunks/framework.Ddwm6YJC.js";const f=JSON.parse('{"title":"第四卷 退潮 · 第80章 档案","description":"","frontmatter":{},"headers":[],"relativePath":"第80章_档案.md","filePath":"第80章_档案.md"}'),n={name:"第80章_档案.md"};function _(c,a,d,l,i,p){return r(),o("div",null,[...a[0]||(a[0]=[e("h1",{id:"第四卷-退潮-·-第80章-档案",tabindex:"-1"},[s("第四卷 退潮 · 第80章 档案 "),e("a",{class:"header-anchor",href:"#第四卷-退潮-·-第80章-档案","aria-label":'Permalink to "第四卷 退潮 · 第80章 档案"'},"​")],-1),e("p",null,"高三那个春天，风里还带着凉意，香樟叶子的气味从半开的窗缝挤进来，混着粉笔灰和纸张的味道。 老周抱着一叠表格走进来，牛皮纸的封皮被他拍得啪啪响，教室里原本的窃窃私语一下子静了。 他说，这是归档用的表格，每个人都要填，理想那一栏，好好想想再落笔。 纸发下来，粗糙的边缘蹭着指腹，有点涩，油墨味很淡，凑近才能闻到。 陈默拿到就转笔，笔杆敲在桌角，发出清脆的嗒嗒声，整个人坐不住。 顾远凑过去看了一眼，笑着说，理想能当饭吃吗，老周耳朵尖，隔着过道喊他，先填了再说。 林小满咬着笔帽，侧头问何晓，你打算写什么，何晓想了很久，说想当老师，留在县里，离家近。 阳光斜斜落在课桌上，灰尘在光柱里浮着，我盯着表格上那行空格看了很久。 同桌的江苒很安静，她把表格压平，用指甲把卷起的角一点点捋平，动作很轻。 我低声问她，你想好了吗，她没抬头，只说，差一点。 老周在过道里慢慢走，鞋底踩在水泥地上，声音很稳，他停在我身后，看了一会儿，说字可以再大方些。 我点点头，笔尖悬在纸面上，墨水在笔尖聚成一个小点，又被纸吸了进去。 我想起旧楼三楼阳台上的晾衣绳，风把床单吹得鼓起来，还有奶奶递过来的热水，喝下去是暖暖的味道。 我想留在雾山，雾山大学就在江边，坐车穿过南雾县的老街就能到，听说图书馆的窗能看到雾起来的样子。 我写下那几个字的时候，手有点抖，墨色洇开一点，像雾散不开的样子。 江苒偏头看了一眼，轻声问，你决定了，我说，嗯，离家近，能照顾到身边的人。 她笑了笑，眼尾弯起来，可那笑里有点别的东西，我说不上来。 她把玩着手里的笔，笔帽上有浅浅的牙印，阳光照在她手背上，细小的绒毛清晰可见。 过了一会儿，她低头写字，笔尖划过纸面，发出沙沙的声响，很慢，很用力。 我忍不住凑过去看，她在理想栏里写的，是南州路。 我愣了一下，问，那是学校吗，她摇头，说，是条路，听说能一直走到海边。 教室里很吵，陈默和顾远还在为谁的理想更实在争论，林小满把头埋进臂弯里笑。 可我那一小片地方忽然很静，只听见窗外叶子被风吹动的声音，还有自己的呼吸。 我说，你想去看海吗，她说，想去闻闻不一样的风，雾山太湿了，衣服总晾不干。 我说，雾山大学也很好，图书馆很大，她说，我知道，只是想往外走走看。 老周走到她身边，拿起表格看了看，没说话，只是轻轻点了点纸面，又放下了。 下课铃响的时候，表格还没收完，纸张翻动的声音一层推着一层，像水漫上来。 江苒从抽屉里摸出一个橘子，推到我手边，橘子皮凉凉的，带着她掌心的温度。 她说，别皱眉，挺丑的，我把橘子攥紧，酸甜还没尝到，喉咙先有点涩。 我问她，什么时候决定的，她说，很久了，只是没找到机会说。 我翻开书，想找点话说，书页里掉出一张卡片，边缘已经毛了，是她之前夹给我的那张。 上面有她画的很淡的雾，铅笔的痕迹快要看不清了，我用指腹摩挲了一下。 陈默在后面喊，你写了啥，我把表格扣过去，说，保密。 顾远笑，说，肯定是雾山大学，你离不开这片雾，我没反驳，只是看着江苒。 她把表格整理好，压在书下，书脊对齐桌角，分毫不差，像她一贯做事的样子。 放学时，老周把表格收齐，抱在怀里，说，这些纸会跟着你们很久，好好对待。 走出教室，楼道里有饭菜的香气，还有潮潮的水汽，江苒走在我前面，发尾轻轻晃着。 我追上去，和她并肩，问她，南州路远吗，她说，挺远的，要换好几次车。 我说，那你会回来吗，她停下脚步，看着走廊尽头那片白亮亮的天。 她说，会吧，只是想先出去看看，雾外面是什么颜色。 风从走廊那头吹过来，带着烟火气和远处操场的尘土味，我忽然觉得手里的书很沉。 晚上我把那个橘子放在桌上，没舍得吃，橘子皮映着台灯的光，卡片就压在下面。 我把留底压在台灯下，看着她写的那几个字，字迹清秀，收笔时带了一点钩，像要飞起来。 而我的那几个字，方方正正，落在纸上，像石头，安稳又笨重。 我想起傍晚收表时老周的眼神，他抱着那叠纸站在门口，目光在我们两人之间停了停，欲言又止。 陈默追出来问我们晚上去不去江边走走，顾远说风大，林小满裹紧外套，说想早点回去。 何晓把围巾分了一半给林小满，两人缩在一起往校门口走，笑声被风吹散。 江苒走得很慢，影子被路灯拉得很长，我跟在她身侧，听见她鞋底碾过落叶的脆响。 我说，南州路那边冬天冷吗，她说，不知道，只听说海风很大，吹在脸上带着咸味。 我说，那你怕冷吗，她抱紧书包带，说，怕，可还是想去。 路过宋阿婆的小店时，灯还亮着，暖黄的光落在青石板上，阿婆在里面摆糖罐，见我们经过，招手让我们进去。 屋里有红糖和姜的香气，阿婆给她塞了两包姜汤，又给我塞了两包，说，天凉，喝一杯暖暖。 江苒低头接过姜汤，轻声说谢谢，阿婆摸摸她的头，说，出去也好，记得回来看看。 走出小店，姜汤暖到心里，我忽然觉得眼睛有点热。 我问她，什么时候开始想这条路的，她望着雾蒙蒙的街口，说，从第一次听说海的时候。 我忽然很想知道，当她写下那条路的时候，心里有没有一刻，想过回头。 就在我要关灯时，桌上的笔滚落下去，砸在卡片上，发出很轻的一声，我的心也跟着跳了一下。 我俯身去捡，发现卡片背面多了一行很小的字，是她的笔迹，墨色还很新，字小到要凑近灯光才能看清，我的手悬在半空，忽然不敢翻过来。",-1)])])}const h=t(n,[["render",_]]);export{f as __pageData,h as default};
